/** TEMP PS S1637 run ka (katalogas v8.7.3 gzip+b64 dalis 1/2 -> ps-backups/kat-v874.part1) */
add_action('init', function(){
  if (!isset($_GET['ps_s1637k4a'])) return;
  $o=array('v'=>'S1637 ka4 part1'); global $wpdb;
  $o['temp_istrinta']=(int)$wpdb->query("DELETE FROM {$wpdb->prefix}snippets WHERE name LIKE 'TEMP%' AND active=0");
  $up=wp_upload_dir(); $bk=trailingslashit($up['basedir']).'ps-backups'; wp_mkdir_p($bk);
  $c='';
  $o['part1']=file_put_contents($bk.'/kat-v874.part1',$c); $o['md5']=md5($c); $o['len']=strlen($c);
